fn torneo(valores: &Vec<i64>, i: usize, j: usize, k: usize) -> (usize, usize) {
    let vi = valores[i];
    let vj = valores[j];
    let vk = valores[k];

    // Find the two indices with the highest values,
    // ordered so that the value at the first index >= value at the second index.
    // The remaining (third) index will have the smallest value.

    // Determine ordering of all three, then pick top two in descending order.
    if vi >= vj && vi >= vk {
        // vi is the largest
        if vj >= vk {
            (i, j) // vi >= vj >= vk
        } else {
            (i, k) // vi >= vk > vj
        }
    } else if vj >= vi && vj >= vk {
        // vj is the largest
        if vi >= vk {
            (j, i) // vj >= vi >= vk
        } else {
            (j, k) // vj >= vk > vi
        }
    } else {
        // vk is the largest
        if vi >= vj {
            (k, i) // vk >= vi >= vj
        } else {
            (k, j) // vk >= vj > vi
        }
    }
}

